/**
 * Acceptance checks against a local server with a disposable DATA_DIR.
 * ADMIN_TEST_DATA_ISOLATED=1 ADMIN_TEST_PASSWORD=<temporary test password>
 * ADMIN_BASE_URL=http://127.0.0.1:3000
 * ADMIN_TEST_RUNTIME=.next-admin-test/verification/runtime.json (generated by the test server)
 * ADMIN_PLAYWRIGHT_MODULE=C:/path/to/playwright/index.mjs (optional)
 * ADMIN_BROWSER_EXECUTABLE=C:/path/to/chrome.exe (optional)
 * Never run this against the live portfolio: the CRUD checks write content.
 */
import assert from "node:assert/strict";
import { mkdir, readFile, writeFile, stat } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";

const runtime = await readFile(
  path.resolve(
    process.env.ADMIN_TEST_RUNTIME ||
      ".next-admin-test/verification/runtime.json",
  ),
  "utf8",
)
  .then(JSON.parse)
  .catch(() => null);
const base = new URL(
  process.env.ADMIN_BASE_URL || runtime?.baseURL || "http://127.0.0.1:3000",
);
assert(
  ["localhost", "127.0.0.1", "[::1]"].includes(base.hostname),
  "Use a loopback test server.",
);
assert(
  process.env.ADMIN_TEST_DATA_ISOLATED === "1" ||
    (runtime?.dataDir &&
      path
        .resolve(runtime.dataDir)
        .startsWith(path.resolve(".next/admin-verification") + path.sep)),
  "Set ADMIN_TEST_DATA_ISOLATED=1 only for a disposable test dataset.",
);
const password = process.env.ADMIN_TEST_PASSWORD || runtime?.password;
assert(
  password,
  "Supply a temporary ADMIN_TEST_PASSWORD matching the isolated server.",
);
const redact = (value) => String(value).replaceAll(password, "[redacted]");
let modulePath = process.env.ADMIN_PLAYWRIGHT_MODULE;
if (modulePath && (await stat(modulePath)).isDirectory())
  modulePath = path.join(modulePath, "index.mjs");
const { chromium } = await import(
  modulePath ? pathToFileURL(modulePath).href : "playwright"
);
const output = path.resolve(".next/admin-verification");
await mkdir(output, { recursive: true });
const browser = await chromium.launch({
  headless: true,
  ...(process.env.ADMIN_BROWSER_EXECUTABLE
    ? { executablePath: process.env.ADMIN_BROWSER_EXECUTABLE }
    : {}),
});
const context = await browser.newContext({
  viewport: { width: 1440, height: 1000 },
  reducedMotion: "reduce",
});
const page = await context.newPage();
page.setDefaultTimeout(15_000);
page.setDefaultNavigationTimeout(60_000);
const report = {
  startedAt: new Date().toISOString(),
  base: base.origin,
  widths: [],
  checks: [],
  runtimeErrors: [],
  consoleErrors: [],
  networkErrors: [],
  screenshots: [],
  limitations: [
    "Cloudinary uploads are not sent. Production domain/cookies and deployed login are not tested by this local harness.",
  ],
};
page.on("pageerror", (error) =>
  report.runtimeErrors.push(redact(error.message)),
);
page.on("console", (message) => {
  if (message.type() === "error")
    report.consoleErrors.push({
      text: redact(message.text()),
      url: message.location().url?.split("?")[0],
    });
});
page.on("requestfailed", (request) =>
  report.networkErrors.push({
    url: request.url().split("?")[0],
    resource: request.resourceType(),
    failure: request.failure()?.errorText,
  }),
);
let nativeDialogAnswer = "dismiss";
page.on(
  "dialog",
  (dialog) =>
    void (nativeDialogAnswer === "accept" ? dialog.accept() : dialog.dismiss()),
);
const sections = [
  { key: "projects", label: "Projects", add: "Add Project" },
  { key: "experience", label: "Experience", add: "Add Experience" },
  { key: "hackathons", label: "Hackathons", add: "Add Hackathon" },
  { key: "events", label: "Community events", add: /Add.*Event/i },
  { key: "socials", label: "Social links", add: /Add.*Link/i },
  { key: "about", label: "About & images" },
];
const suffix = Date.now().toString(36);
const created = [];
const url = (pathname) => new URL(pathname, base).href;
const api = async (collection) => {
  const response = await context.request.get(
    url(`/api/admin/content?collection=${collection}`),
  );
  assert.equal(response.status(), 200);
  return response.json();
};

async function check(name, action) {
  const start = Date.now();
  try {
    await action();
    report.checks.push({ name, passed: true, elapsedMs: Date.now() - start });
    console.log(`PASS ${name}`);
  } catch (error) {
    report.checks.push({
      name,
      passed: false,
      error: redact(error.message),
      elapsedMs: Date.now() - start,
    });
    console.error(`FAIL ${name}: ${redact(error.message)}`);
    throw error;
  }
}

async function settled() {
  await page.locator(".admin-page-content").waitFor({ state: "visible" });
  await page.waitForFunction(
    () =>
      document
        .querySelector(".admin-page-content")
        ?.getAttribute("aria-busy") === "false",
  );
  assert.equal(
    await page.getByRole("button", { name: "Retry", exact: true }).count(),
    0,
    "Content loading failed.",
  );
}

async function navigate(section) {
  const menu = page.getByRole("button", {
    name: "Open navigation",
    exact: true,
  });
  if (await menu.isVisible()) await menu.click();
  await page
    .getByRole("navigation", { name: "Content sections", exact: true })
    .getByRole("button", {
      name: new RegExp(
        `^${section.label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?:\\s|$)`,
      ),
    })
    .click();
  await page.waitForURL(new RegExp(`#${section.key}$`));
  await settled();
}

async function screenshot(name) {
  const file = `${name}.png`;
  await page.screenshot({
    path: path.join(output, file),
    animations: "disabled",
  });
  report.screenshots.push(file);
}

async function layoutCheck(name, { modal = false } = {}) {
  const geometry = await page.evaluate(() => {
    const width = window.innerWidth;
    const visible = (element) => {
      const box = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      return (
        box.width > 0 &&
        box.height > 0 &&
        style.visibility !== "hidden" &&
        style.display !== "none" &&
        !element.closest("[inert]")
      );
    };
    const fields = [
      ...document.querySelectorAll(
        ".admin-main input:not([type=hidden]), .admin-main textarea, .admin-main select, .admin-modal-box, .admin-page-content, .admin-login-panel",
      ),
    ].filter(visible);
    return {
      width,
      scrollWidth: document.documentElement.scrollWidth,
      overflowing: fields
        .filter((element) => {
          const r = element.getBoundingClientRect();
          return r.left < -1 || r.right > width + 1;
        })
        .map((element) => ({
          tag: element.tagName,
          id: element.id,
          class: typeof element.className === "string" ? element.className : "",
          left: element.getBoundingClientRect().left,
          right: element.getBoundingClientRect().right,
        })),
      dialogs: [...document.querySelectorAll(".admin-modal-box")]
        .filter(visible)
        .map((element) => {
          const r = element.getBoundingClientRect();
          return {
            top: r.top,
            bottom: r.bottom,
            height: r.height,
            viewport: window.innerHeight,
          };
        }),
      tinyTargets: [
        ...document.querySelectorAll(".admin-workspace button:not(:disabled)"),
      ]
        .filter(visible)
        .filter(
          (element) =>
            !element.matches(".admin-drawer-backdrop, .admin-drag-handle") &&
            !element.closest(".admin-sidebar:not(.is-open)") &&
            element.getBoundingClientRect().height < 40,
        )
        .map((element) => ({
          name:
            element.getAttribute("aria-label") || element.textContent?.trim(),
          height: element.getBoundingClientRect().height,
        })),
    };
  });
  assert(
    geometry.scrollWidth <= geometry.width + 1,
    `${name}: page horizontally overflows by ${geometry.scrollWidth - geometry.width}px`,
  );
  assert.deepEqual(
    geometry.overflowing,
    [],
    `${name}: horizontally clipped fields/panels`,
  );
  if (geometry.width <= 768)
    assert.deepEqual(
      geometry.tinyTargets,
      [],
      `${name}: touch targets under 40px high`,
    );
  if (modal) {
    assert(geometry.dialogs.length > 0, `${name}: no dialog visible`);
    for (const dialog of geometry.dialogs)
      assert(
        dialog.top >= -1 && dialog.bottom <= dialog.viewport + 1,
        `${name}: dialog extends outside viewport`,
      );
  }
}

async function closeEditor() {
  await page
    .getByRole("dialog")
    .last()
    .getByRole("button", { name: "Cancel", exact: true })
    .click();
  const discard = page.getByRole("button", {
    name: "Discard changes",
    exact: true,
  });
  if (await discard.isVisible().catch(() => false)) await discard.click();
  await waitEditorsClosed();
}

async function waitEditorsClosed() {
  await page.waitForFunction(
    () =>
      ![...document.querySelectorAll(".admin-modal-box")].some(
        (dialog) => dialog.getBoundingClientRect().width > 0,
      ),
  );
}

async function saveEditor(label) {
  const response = page.waitForResponse(
    (response) =>
      response.url().endsWith("/api/admin/content") &&
      ["POST", "PATCH"].includes(response.request().method()),
  );
  await page
    .getByRole("dialog")
    .last()
    .getByRole("button", { name: label, exact: true })
    .click();
  const saved = await response;
  assert(saved.ok(), `Save returned ${saved.status()}: ${await saved.text()}`);
  await waitEditorsClosed();
  await settled();
  return saved.json();
}

try {
  await check("unauthenticated direct routes are protected", async () => {
    assert.equal(
      (
        await context.request.get(url("/api/admin/content?collection=projects"))
      ).status(),
      401,
    );
    await page.goto(url("/secret-admin"));
    await page.waitForURL(/\/secret-admin\/login/);
  });
  await check("login layouts at all requested widths", async () => {
    for (const width of [320, 375, 430, 768, 1024, 1440, 1920, 2560]) {
      await page.setViewportSize({ width, height: width < 768 ? 844 : 1000 });
      await page.getByLabel("Password", { exact: true }).fill("");
      await layoutCheck(`login ${width}`);
      await screenshot(`login-${width}`);
    }
  });
  await check(
    "invalid login, password visibility, keyboard login",
    async () => {
      await page
        .getByLabel("Password", { exact: true })
        .fill(`incorrect-${suffix}`);
      await page
        .getByRole("button", { name: "Show password", exact: true })
        .click();
      assert.equal(
        await page.getByLabel("Password", { exact: true }).getAttribute("type"),
        "text",
      );
      await page
        .getByRole("button", { name: "Hide password", exact: true })
        .click();
      await page.getByRole("button", { name: "Sign in to workspace" }).click();
      await page.getByRole("alert").waitFor();
      await page.getByLabel("Password", { exact: true }).fill(password);
      await page.getByLabel("Password", { exact: true }).press("Enter");
      await page.waitForURL(
        (candidate) => candidate.pathname === "/secret-admin",
      );
      await settled();
      assert(
        !(await page
          .locator("body")
          .innerText()
          .then((text) => text.includes(password))),
        "Configured password appeared in the page.",
      );
    },
  );
  await check(
    "refresh and direct section navigation preserve session",
    async () => {
      await page.reload();
      await settled();
      await page.goto(url("/secret-admin#events"));
      await settled();
      await page
        .getByRole("heading", { name: /Community Events.*HackShastra/i })
        .waitFor();
    },
  );

  await check(
    "CRUD for projects, experience, hackathons, events, and social links",
    async () => {
      await page.setViewportSize({ width: 1440, height: 1000 });
      const records = [
        {
          section: sections[0],
          collection: "projects",
          name: `Verification project ${suffix}`,
          titleLabel: "Project Title",
          save: "Save Project",
          fields: {
            Description: "Browser acceptance draft.",
            "Cover Image URL":
              "https://images.unsplash.com/photo-1550745165-9bc0b252726f",
          },
        },
        {
          section: sections[1],
          collection: "experiences",
          name: `Verification role ${suffix}`,
          titleLabel: "Role Title",
          save: "Save Experience",
          fields: {
            "Company Name": "Verification studio",
            Description: "Browser acceptance role.",
          },
        },
        {
          section: sections[2],
          collection: "hackathons",
          name: `Verification hackathon ${suffix}`,
          titleLabel: "Hackathon Name",
          save: "Save Hackathon",
          fields: {
            Organizer: "Verification studio",
            Description: "Browser acceptance hackathon.",
          },
        },
        {
          section: sections[3],
          collection: "events",
          name: `Verification event ${suffix}`,
          titleLabel: /Event title/,
          save: "Save event",
          fields: { "Event date": "06-11-2026" },
        },
        {
          section: sections[4],
          collection: "socials",
          name: `Verification social ${suffix}`,
          titleLabel: "Platform Label",
          save: "Save Social Link",
          fields: {
            "Handle / Username": "@verification",
            "Full Profile Link URL": "https://example.com/verification",
          },
        },
      ];
      for (const record of records) {
        await navigate(record.section);
        await page
          .getByRole("button", {
            name: record.section.add,
            exact: typeof record.section.add === "string",
          })
          .click();
        const dialog = page.getByRole("dialog").last();
        await dialog
          .getByLabel(record.titleLabel, {
            exact: typeof record.titleLabel === "string",
          })
          .fill(record.name);
        for (const [label, value] of Object.entries(record.fields))
          await dialog
            .getByLabel(label, { exact: label !== "Event date" })
            .fill(value);
        const createdRecord = await saveEditor(record.save);
        created.push({ collection: record.collection, id: createdRecord.id });
        assert(
          (await api(record.collection)).some(
            (row) => row.id === createdRecord.id,
          ),
          "Created record absent from API.",
        );
        const row = page
          .locator(".admin-sortable-row")
          .filter({ hasText: record.name });
        await row.getByRole("button", { name: "Edit", exact: true }).click();
        await page
          .getByRole("dialog")
          .last()
          .getByLabel(record.titleLabel, {
            exact: typeof record.titleLabel === "string",
          })
          .fill(`${record.name} edited`);
        await saveEditor(record.save);
        const updated = (await api(record.collection)).find(
          (candidate) => candidate.id === createdRecord.id,
        );
        assert(
          Object.values(updated).includes(`${record.name} edited`),
          "Edited text did not persist.",
        );
        await page
          .locator(".admin-sortable-row")
          .filter({ hasText: `${record.name} edited` })
          .getByRole("button", { name: "Delete", exact: true })
          .click();
        await page
          .getByRole("dialog")
          .last()
          .getByRole("button", { name: "Delete item", exact: true })
          .click();
        await page.waitForFunction(
          (name) =>
            ![...document.querySelectorAll(".admin-sortable-row")].some((row) =>
              row.textContent.includes(name),
            ),
          `${record.name} edited`,
        );
        await settled();
        assert(
          !(await api(record.collection)).some(
            (candidate) => candidate.id === createdRecord.id,
          ),
          "Deleted record remains in API.",
        );
      }
    },
  );

  await check(
    "publishing, featuring, and keyboard ordering persist",
    async () => {
      await navigate(sections[0]);
      const initial = await api("projects");
      assert(
        initial.length >= 2,
        "Seed at least two projects in the disposable dataset.",
      );
      const firstRow = page.locator(".admin-sortable-row").first();
      for (const [label, field] of [
        [/Published|Draft/, "isPublished"],
        [/Featured|Standard/, "featured"],
      ]) {
        await firstRow
          .getByRole("button", { name: label, exact: true })
          .click();
        await settled();
        assert.equal(
          (await api("projects")).find((item) => item.id === initial[0].id)[
            field
          ],
          !initial[0][field],
        );
        await firstRow
          .getByRole("button", { name: label, exact: true })
          .click();
        await settled();
      }
      await firstRow
        .getByRole("button", { name: "Move item 1 down", exact: true })
        .focus();
      await page.keyboard.press("Enter");
      await page.waitForFunction(
        () =>
          document
            .querySelector(".admin-sortable-list")
            ?.getAttribute("aria-busy") === "false",
      );
      assert.equal((await api("projects"))[1].id, initial[0].id);
      await page
        .locator(".admin-sortable-row")
        .nth(1)
        .getByRole("button", { name: "Move item 2 up", exact: true })
        .click();
      await page.waitForFunction(
        () =>
          document
            .querySelector(".admin-sortable-list")
            ?.getAttribute("aria-busy") === "false",
      );
      assert.equal((await api("projects"))[0].id, initial[0].id);
    },
  );

  await check(
    "About draft discard, failed save preservation, and successful save",
    async () => {
      await navigate(sections[5]);
      const field = page.getByLabel("Main heading", { exact: false }).first();
      const target = (await field.count())
        ? field
        : page.locator(".admin-card textarea").first();
      const original = await target.inputValue();
      const draft = "Browser verification draft";
      await target.fill(draft);
      nativeDialogAnswer = "accept";
      await page
        .getByRole("button", { name: "Discard changes", exact: true })
        .click();
      nativeDialogAnswer = "dismiss";
      assert.equal(await target.inputValue(), original);
      await target.fill(draft);
      await page.route("**/api/admin/content", async (route) => {
        if (route.request().method() === "PATCH")
          await route.fulfill({
            status: 500,
            contentType: "application/json",
            body: JSON.stringify({ error: "Verification: save unavailable" }),
          });
        else await route.continue();
      });
      await page
        .getByRole("button", { name: "Save About page", exact: true })
        .click();
      await page
        .getByText("Your draft is still here.", { exact: false })
        .waitFor();
      assert.equal(await target.inputValue(), draft);
      await page.unroute("**/api/admin/content");
      await target.fill(original);
      await page
        .getByRole("button", { name: "Save About page", exact: true })
        .click();
      await settled();
      await page
        .getByRole("button", { name: "Save About page", exact: true })
        .waitFor({ state: "visible" });
      await page.waitForFunction(
        () => !document.body.textContent.includes("Unsaved About changes"),
      );
    },
  );

  await check(
    "all six sections and all five editor dialogs at every width",
    async () => {
      for (const width of [320, 375, 430, 768, 1024, 1440, 1920, 2560]) {
        await page.setViewportSize({ width, height: width < 768 ? 844 : 1000 });
        for (const section of sections) {
          await navigate(section);
          await layoutCheck(`${section.key} ${width}`);
          await screenshot(`${section.key}-${width}`);
          if (section.add) {
            await page
              .getByRole("button", {
                name: section.add,
                exact: typeof section.add === "string",
              })
              .click();
            await page.getByRole("dialog").last().waitFor({ state: "visible" });
            await layoutCheck(`${section.key} editor ${width}`, {
              modal: true,
            });
            const dialog = page.getByRole("dialog").last();
            const controls = dialog.locator(
              "button:not(:disabled), input:not(:disabled), textarea:not(:disabled), select:not(:disabled)",
            );
            await controls.last().focus();
            await page.keyboard.press("Tab");
            assert(
              await dialog.evaluate((node) =>
                node.contains(document.activeElement),
              ),
              "Tab escaped the dialog.",
            );
            await screenshot(`${section.key}-editor-${width}`);
            await closeEditor();
          }
        }
        report.widths.push(width);
      }
    },
  );

  await check(
    "mobile drawer keyboard navigation and browser back",
    async () => {
      await page.setViewportSize({ width: 375, height: 844 });
      await navigate(sections[0]);
      await navigate(sections[1]);
      await page.goBack();
      await page.waitForURL(/#projects$/);
      await settled();
      await page
        .getByRole("button", { name: "Open navigation", exact: true })
        .click();
      const drawer = page.getByRole("dialog", { name: "Workspace navigation" });
      await drawer.locator("button:not(:disabled), a[href]").last().focus();
      await page.keyboard.press("Tab");
      assert(
        await drawer.evaluate((node) => node.contains(document.activeElement)),
        "Tab escaped mobile navigation.",
      );
      await page.keyboard.press("Escape");
      assert.equal(
        await page
          .getByRole("button", { name: "Open navigation", exact: true })
          .getAttribute("aria-expanded"),
        "false",
      );
    },
  );

  await check("logout blocks cookie replay and protected routes", async () => {
    const cookies = await context.cookies();
    const session = cookies.find((cookie) => cookie.name === "spider-session");
    assert(session?.httpOnly, "Session must be HttpOnly.");
    assert.equal(session.sameSite, "Strict");
    const menu = page.getByRole("button", {
      name: "Open navigation",
      exact: true,
    });
    if (await menu.isVisible()) await menu.click();
    await page.getByRole("button", { name: "Sign out", exact: true }).click();
    await page.waitForURL(/\/secret-admin\/login/);
    assert.equal(
      (
        await context.request.get(url("/api/admin/content?collection=projects"))
      ).status(),
      401,
    );
    assert.equal(
      (
        await context.request.get(
          url("/api/admin/content?collection=projects"),
          { headers: { Cookie: `${session.name}=${session.value}` } },
        )
      ).status(),
      401,
      "Logged-out cookie replay must fail.",
    );
    await page.goto(url("/secret-admin"));
    await page.waitForURL(/\/secret-admin\/login/);
  });
  assert.deepEqual(
    report.runtimeErrors,
    [],
    "Unexpected browser JavaScript errors.",
  );
} catch (error) {
  // Avoid error screenshots during login, where a test credential may be visible.
  if (!page.url().includes("/login"))
    await screenshot("failure-state").catch(() => {});
  process.exitCode = 1;
  console.error(redact(error.message));
} finally {
  if (
    report.networkErrors.some(
      (error) =>
        error.resource === "image" &&
        error.failure === "net::ERR_NETWORK_ACCESS_DENIED",
    )
  ) {
    report.limitations.push(
      "Remote image loading was blocked by the test environment. Image controls and layout were verified; successful remote delivery and real uploads were not.",
    );
  }
  report.finishedAt = new Date().toISOString();
  report.passed =
    report.checks.every((item) => item.passed) &&
    report.checks.length === 10 &&
    report.runtimeErrors.length === 0 &&
    process.exitCode !== 1;
  report.createdRecordCount = created.length;
  await writeFile(
    path.join(output, "report.json"),
    JSON.stringify(report, null, 2),
  );
  await browser.close();
  console.log(`Admin verification report: ${path.join(output, "report.json")}`);
}
